-- Additive registry. No existing CRM rows are moved, copied or relabelled.
CREATE TABLE "SaasOrganization" ("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"schemaName" TEXT NOT NULL UNIQUE,"status" TEXT NOT NULL DEFAULT 'PENDING',"schemaVersion" TEXT,"settings" JSONB NOT NULL DEFAULT '{}',"provisioningAttempts" INTEGER NOT NULL DEFAULT 0,"lastErrorCode" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,
 CHECK("status" IN ('LEGACY','PENDING','READY','FAILED','SUSPENDED')),CHECK(("schemaName"='public' AND "id"='proclair-legacy' AND "status"='LEGACY') OR "schemaName" ~ '^tenant_[a-f0-9]{32}$'));
CREATE TABLE "SaasUser" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SaasMembership" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL REFERENCES "SaasOrganization"("id") ON DELETE RESTRICT,"userId" TEXT NOT NULL REFERENCES "SaasUser"("id") ON DELETE RESTRICT,"role" TEXT NOT NULL DEFAULT 'OWNER',"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("organizationId","userId"),CHECK("role" IN ('OWNER','ADMIN','GENERAL_MANAGER','SALES_MANAGER','OPERATIONS_MANAGER','SELLER','TECHNICIAN','OFFICE')));
CREATE INDEX "SaasMembership_userId_active_idx" ON "SaasMembership"("userId","active");
CREATE TABLE "SaasSession" ("tokenHash" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "SaasUser"("id") ON DELETE CASCADE,"expiresAt" TIMESTAMP(3) NOT NULL,"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "SaasSession_userId_expiresAt_idx" ON "SaasSession"("userId","expiresAt");
CREATE TABLE "SaasPlan" ("code" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"monthlyPriceCents" INTEGER CHECK("monthlyPriceCents">=0),"currency" TEXT NOT NULL DEFAULT 'CAD' CHECK("currency"='CAD'),"policy" JSONB NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"version" INTEGER NOT NULL DEFAULT 1 CHECK("version">0));
CREATE TABLE "SaasSubscription" ("organizationId" TEXT PRIMARY KEY REFERENCES "SaasOrganization"("id") ON DELETE RESTRICT,"planCode" TEXT NOT NULL REFERENCES "SaasPlan"("code") ON DELETE RESTRICT,"status" TEXT NOT NULL DEFAULT 'TRIALING' CHECK("status" IN ('TRIALING','ACTIVE','CANCELLED','PAST_DUE','SUSPENDED')),"trialEndsAt" TIMESTAMP(3),"version" INTEGER NOT NULL DEFAULT 1,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "SaasIntegration" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL REFERENCES "SaasOrganization"("id") ON DELETE RESTRICT,"provider" TEXT NOT NULL CHECK("provider" IN ('STRIPE','TWILIO','MAPS','EMAIL','SIGNATURE','AI')),"encryptedSecret" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'UNVERIFIED' CHECK("status" IN ('UNVERIFIED','VERIFIED','ERROR','DISABLED')),"externalAccountId" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("organizationId","provider"),UNIQUE("provider","externalAccountId"));
CREATE TABLE "SaasEvent" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL REFERENCES "SaasOrganization"("id") ON DELETE RESTRICT,"actorId" TEXT NOT NULL,"action" TEXT NOT NULL,"details" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "SaasEvent_organizationId_createdAt_idx" ON "SaasEvent"("organizationId","createdAt");
INSERT INTO "SaasOrganization" ("id","slug","name","schemaName","status","updatedAt") VALUES ('proclair-legacy','proclair','Proclair Inc.','public','LEGACY',CURRENT_TIMESTAMP);
CREATE TABLE "SaasInvitation" ("tokenHash" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL REFERENCES "SaasOrganization"("id") ON DELETE RESTRICT,"email" TEXT NOT NULL,"role" TEXT NOT NULL CHECK("role" IN ('ADMIN','GENERAL_MANAGER','SALES_MANAGER','OPERATIONS_MANAGER','SELLER','TECHNICIAN','OFFICE')),"createdBy" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"usedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "SaasInvitation_organizationId_expiresAt_idx" ON "SaasInvitation"("organizationId","expiresAt");
